  const taskSeeds = {
    t101:['完成 Hydra 产品对比内容初稿','Draft the Hydra product comparison','让客户看懂不同产品的适用场景、差异与选择依据。','Help customers understand use cases, differences and selection criteria for each product.',['内容覆盖约定的三个使用场景','Cover the three agreed use cases','关键规格注明来源，不加入未经核实的参数','Cite sources for key specifications; exclude unverified claims','提交完整文稿与配图清单','Submit the complete draft and image list']],
    t102:['10 月获客实验：落地页首屏复盘','October acquisition test: landing-page hero review','对两个首屏版本的实际转化结果做复盘，给出下一步可验证的实验。','Review actual conversion results from two hero variants and propose a testable next experiment.',['说明实验目标、起止时间与版本差异','Explain the goal, test dates and variant differences','提供样本量、转化指标及数据来源','Provide sample sizes, conversion metrics and data sources','给出与数据一致的结论和后续行动','Provide evidence-based findings and next steps']],
    t103:['整理客户高频问题与内容选题','Organize customer FAQs and content ideas','从客户反馈中整理可追溯的常见问题，形成下周选题。','Turn traceable customer feedback into an FAQ list and next week’s content ideas.',['问题可回溯到客户反馈记录','Link each question to customer feedback','按使用场景归类，去除重复问题','Group by use case and remove duplicates','形成至少五个明确的内容选题','Define at least five clear content topics']],
    t104:['官网询盘漏斗数据核对','Validate the website inquiry funnel','核对访问到询盘各环节的数据口径，先确认一致性再做判断。','Validate metric definitions from visits through inquiries before drawing conclusions.',['列明每个转化环节的计算口径','Document definitions for each conversion stage','提供原始数据或可访问的报表','Provide source data or an accessible report','解释异常数据及处理方式','Explain anomalies and how they were handled']],
    t105:['确认 11 月内容计划与验收标准','Confirm November content plan and criteria','与内容和增长同事确认月度计划，保证任务有明确成果定义。','Agree on the monthly plan with Content and Growth, with clear outcomes for every task.',['内容排期与产品重点一致','Align the content calendar with product priorities','每项任务有负责人、截止时间和成果标准','Give every task an owner, due date and outcome criteria','负责人确认资源和前置依赖','Have owners confirm resources and dependencies']],
    t106:['发布 VertiGo 使用场景内容','Publish VertiGo use-case content','将已经确认的使用场景整理成对外内容，并保留发布证据。','Publish verified use cases and retain evidence of the release.',['内容事实与已确认资料一致','Keep factual claims consistent with verified material','页面在桌面和移动端可阅读','Make the page readable on desktop and mobile','保留发布地址、日期和复核记录','Retain the URL, release date and review record']],
    t107:['渠道活动线索去重与归因','Deduplicate and attribute campaign leads','整理活动线索，明确有效线索标准与来源，交接给销售。','Organize campaign leads, define qualification and attribution, and hand them over to Sales.',['按约定规则去重','Deduplicate using the agreed rules','标明有效线索判断与渠道来源','Document qualification decisions and channel sources','完成销售交接并保留确认记录','Complete the Sales handover and retain confirmation']],
    t108:['下周内容的客户案例提纲','Outline next week’s customer case study','把客户需求、制作过程与结果组织成结构清楚的案例提纲。','Outline a clear case study covering customer needs, production process and results.',['提供客户授权或公开素材依据','Provide customer authorization or public-source evidence','故事结构包含需求、过程和结果','Structure the story around need, process and outcome','待核实信息单独标注','Flag information still awaiting verification']],
    t109:['核心询盘表单异常修复','Fix errors in the core inquiry form','修复询盘表单异常并提交测试与发布记录。','Fix inquiry-form errors and submit test and release records.',['复现步骤与问题原因明确','Document reproduction steps and root cause','核心输入和异常场景通过测试','Test core inputs and error scenarios','提交代码、测试和回滚记录','Submit code, test results and rollback records']],
    t110:['产品详情页移动端体验改进','Improve the mobile product detail page','完成移动端信息层级与交互调整，减少阅读和操作障碍。','Improve mobile hierarchy and interactions to reduce reading and usability barriers.',['关键内容在移动端完整可读','Keep key content complete and readable on mobile','核心操作满足约定的交互要求','Meet the agreed requirements for core interactions','提交设计说明和验收对照','Submit design rationale and an acceptance comparison']],
    t111:['发布检查脚本整理','Package reusable release-check scripts','把重复发布检查整理成可重用的脚本和操作说明。','Turn repetitive release checks into reusable scripts and operating instructions.',['脚本覆盖约定的检查清单','Cover the agreed release checklist','异常能返回清楚的错误信息','Return clear error messages when checks fail','其他同事按文档能复现','Ensure another colleague can reproduce the steps']],
    t112:['确认新版页面体验验收清单','Confirm the new page UX acceptance checklist','统一产品与设计的验收标准，减少验收阶段的返工。','Align Product and Design acceptance criteria to reduce review-stage rework.',['清单覆盖核心页面和流程','Cover core pages and flows','每一项有可观察的通过条件','Define observable pass criteria for each item','负责人确认清单版本','Have the owner confirm the checklist version']]
  };
